export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export let settings=SETTINGS,projects=[],catalogProducts=APPAREL_PRODUCTS;
export async function loadServices(){const embedded=typeof document!=='undefined'&&document.querySelector('[data-service-bootstrap]');if(embedded){try{const data=JSON.parse(embedded.textContent);settings=data.settings;projects=data.projects;catalogProducts=data.products;return;}catch{}}try{const [a,b,c]=await Promise.all([fetch('/api/service-settings'),fetch('/api/projects'),fetch('/api/products')]);if(a.ok)settings=await a.json();if(b.ok)projects=(await b.json()).projects;if(c.ok)catalogProducts=(await c.json()).products;}catch{}if(!document.querySelector('[href="/services.css"]')){const l=document.createElement('link');l.rel='stylesheet';l.href='/services.css';document.head.append(l);}}
const section=(body,cls='')=>`<section class="sec ${cls}"><div class="wrap">${body}</div></section>`;
const image=(src,alt)=>`<img src="${esc(src)}" alt="${esc(alt)}" loading="lazy">`;
