if(path==='/design-agreement'||path==='/installation-terms'){const design=path==='/design-agreement';return {title:design?'Design Policy':'Installation Terms',html:section(`<a href="/satin/">Satin Graphic</a><h1 class="d2">${design?'Design Policy & Vehicle Wrap Agreement':'Installation Terms'}</h1>${design?'<div class="card"><h2>Design service fees</h2><p>Offset printing: $100 · Window graphics: $150 · Vehicle estimators: $250. Fees are in CAD, before HST, and are added once when you select I need a designer.</p><p>The vehicle wrap agreement below applies to vehicle wrap design. Other products use the design fee shown on their product page; our team confirms the scope before work begins.</p></div>':''}<div class="terms-prose">${esc(design?settings.designTerms:settings.installationTerms)}</div><p>Questions? <a href="mailto:${esc(settings.designEmail)}">${esc(settings.designEmail)}</a></p>`)};}
