export function printBanner(){const b=settings.printBanner;return section(`<div class="service-banner print-studio-banner">${image(b.image,'Designer creating artwork on a computer')}<div><span class="eyebrow">Design Studio</span><h2 class="d2">${esc(b.title)}</h2><p>${esc(b.text)}</p><a class="btn" href="${esc(b.link)}">Open Design Studio ↗</a></div></div>`);}
