if(path==='/vehicle-wraps/color-change'){const stage=root.querySelector('[data-finish-stage]');if(stage){const split=stage.parentElement;split.innerHTML=`<div><span class="eyebrow">3M wrap finishes</span><h2 class="d2">Pick a finish.</h2><fieldset><legend>Finish</legend><div class="finish-options">${['Gloss','Matte','Satin'].map((f,i)=>`<button class="btn ghost" data-tesla-finish="${f.toLowerCase()}" aria-pressed="${i===0}">${f}</button>`).join('')}</div></fieldset><fieldset><legend>Colour</legend><div class="finish-options">${[['black','#151515'],['white','#fff'],['graphite','#555960'],['red','#b51629'],['pink','#e88ba8']].map(([c,h],i)=>`<button class="colour-choice" data-tesla-colour="${c}" aria-pressed="${i===0}"><span style="background:${h}"></span>${c==='graphite'?'Dark grey':c[0].toUpperCase()+c.slice(1)}</button>`).join('')}</div></fieldset><p data-finish-caption>Gloss · Black</p><p class="small">Illustrative preview; confirm your exact 3M colour with a physical film sample.</p></div><div class="tesla-stage"><img data-tesla src="/satin/img/tesla-black-gloss.png" alt="Tesla in black gloss, side view"></div>`;let colour='black',finish='gloss';split.onclick=e=>{const f=e.target.closest('[data-tesla-finish]'),c=e.target.closest('[data-tesla-colour]');if(!f&&!c)return;if(f)finish=f.dataset.teslaFinish;if(c)colour=c.dataset.teslaColour;split.querySelectorAll('[data-tesla-finish]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.teslaFinish===finish));split.querySelectorAll('[data-tesla-colour]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.teslaColour===colour));const im=split.querySelector('[data-tesla]');im.src='/satin/img/tesla-'+(colour==='pink'?'red':colour)+'-'+finish+'.png';im.style.filter=colour==='pink'?'hue-rotate(330deg) saturate(.65) brightness(1.25)':'';im.alt='Tesla in '+colour+' '+finish+', side view';split.querySelector('[data-finish-caption]').textContent=finish+' · '+colour;};}}
if(path==='/vehicle-wraps'||path==='/vehicle-wraps/commercial'){container.insertAdjacentHTML('beforeend',section('<div class="tint-shortcut"><h2>Finish the look with window tint.</h2><p>Explore vehicle tint film and coverage options.</p><a class="btn" href="/satin/window-tint/vehicle/">Vehicle window tint ↗</a></div>'));}
